```yaml
name: Comment Artifacts

on:
  workflow_run:
    workflows: ["Test and Build"]
    types:
      - completed

permissions:
  contents: read
  pull-requests: write
  actions: read

jobs:
  comment-artifacts:
    runs-on: ubuntu-latest
    if: >-
      github.event.workflow_run.event == 'pull_request' &&
      github.event.workflow_run.conclusion == 'success'
    steps:
      - name: Get PR number
        id: get-pr
        uses: actions/github-script@v7
        with:
          script: |
            const workflowRunId = context.payload.workflow_run.id;

            // Find the specific run associated with the PR
            // We need to look at the pull requests associated with the workflow run
            const { data: pullRequests } = await github.rest.actions.listWorkflowRunPullRequests({
              owner: context.repo.owner,
              repo: context.repo.repo,
              run_id: workflowRunId
            });

            if (pullRequests.pull_requests.length > 0) {
              const prNumber = pullRequests.pull_requests[0].number;
              core.setOutput('pr_number', prNumber);
              return prNumber;
            } else {
              core.setFailed('No pull request found for this workflow run');
              return null;
            }

      - name: Download Artifacts
        uses: actions/download-artifact@v4
        with:
          run-id: ${{ github.event.workflow_run.id }}
          path: artifacts

      - name: List Artifacts
        id: list-artifacts
        run: |
          echo "=== Artifacts Directory ==="
          ls -la artifacts/

          # Find ISO files
          ISO_FILES=$(find artifacts/ -name "*.iso" -type f 2>/dev/null || true)
          if [ -z "$ISO_FILES" ]; then
            echo "No ISO files found"
            exit 0
          fi

          # Create a list of artifact names and sizes
          ARTIFACT_INFO=""
          for iso in $ISO_FILES; do
            FILENAME=$(basename "$iso")
            SIZE=$(du -h "$iso" | cut -f1)
            ARTIFACT_INFO="${ARTIFACT_INFO}- **${FILENAME}** (${SIZE})\n"
          done

          echo "artifact_info<<EOF" >> $GITHUB_OUTPUT
          echo "$ARTIFACT_INFO" >> $GITHUB_OUTPUT
          echo "EOF" >> $GITHUB_OUTPUT

      - name: Post Comment to PR
        if: steps.list-artifacts.outputs.artifact_info != ''
        uses: actions/github-script@v7
        with:
          script: |
            const prNumber = parseInt(process.env.PR_NUMBER);
            const artifactInfo = process.env.ARTIFACT_INFO;

            const commentBody = `## 📦 Build Artifacts

            The following ISO artifacts were generated for this PR:

            ${artifactInfo}

            > 💡 **Note:** Artifacts are available for 90 days after the workflow run.

            ---
            *Auto-generated by GitHub Actions*`;

            // Check if a comment already exists from this workflow
            const { data: comments } = await github.rest.issues.listComments({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: prNumber,
            });

            const existingComment = comments.find(comment => 
              comment.user.type === 'Bot' && 
              comment.body.includes('Build Artifacts') &&
              comment.body.includes('Auto-generated by GitHub Actions')
            );

            if (existingComment) {
              // Update existing comment
              await github.rest.issues.updateComment({
                owner: context.repo.owner,
                repo: context.repo.repo,
                comment_id: existingComment.id,
                body: commentBody
              });
              console.log('Updated existing comment');
            } else {
              // Create new comment
              await github.rest.issues.createComment({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: prNumber,
                body: commentBody
              });
              console.log('Created new comment');
            }
        env:
          PR_NUMBER: ${{ steps.get-pr.outputs.pr_number }}
          ARTIFACT_INFO: ${{ steps.list-artifacts.outputs.artifact_info }}
```

